vulnerable_function:
Object.keys(shims).forEach(function (k) {
  var val = shims[k]
    , exp = val && val.exports;

  if (exp && /^global\:/.test(exp)) {
    exposeGlobals[k] = exp;
  } else {
    onlyShims[k] = val;
  }
}

patched_function:
Object.keys(shims).forEach(function (k) {
  // https://github.com/thlorenz/browserify-shim/issues/245
  if (k === '__proto__' || k === 'constructor') {
    return;
  }

  var val = shims[k]
    , exp = val && val.exports;

  if (exp && /^global\:/.test(exp)) {
    exposeGlobals[k] = exp;
  } else {
    onlyShims[k] = val;
  }
}

